script.setup:
ctx.state.a=await ctx.utils.loadTexture("input.png"); ctx.state.b=await ctx.utils.loadTexture("result.png"); ctx.state.p=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_input; uniform sampler2D u_result; uniform vec2 u_resolution; uniform float u_reveal;
void main(){float aspect=640.0/360.0; float view=u_resolution.x/u_resolution.y; vec2 q=(v_uv-0.5)*vec2(max(1.0,view/aspect),max(1.0,aspect/view))+0.5;
if(any(lessThan(q,vec2(0)))||any(greaterThan(q,vec2(1)))){outColor=vec4(0.055,0.065,0.08,1);return;}
vec3 c=q.x<u_reveal?texture(u_result,q).rgb:texture(u_input,q).rgb;
if(u_reveal>0.001&&u_reveal<0.999&&abs(q.x-u_reveal)<0.002)c=vec3(1,0.8,0.25);outColor=vec4(c,1);}
");
